 const active=[...form.querySelectorAll(':scope > .panel')].find(p=>p.querySelector('h2')?.textContent==='Story & project');
 if(!active)return;
 const wrap=document.createElement('div');wrap.className='generation-mode-columns';form.insertBefore(wrap,active);
