  const column=document.createElement('section');column.className='generation-mode-column'+(enabled?' active':' inactive');
  column.innerHTML=`<div class="generation-mode-heading"><h2>${mode==='agent'?'Agent Mode':'Ingredients Mode'}</h2><label class="generation-mode-switch"><input type="checkbox" id="mode-toggle-${mode}" data-generation-mode="${mode}" ${enabled?'checked':''}><span>${enabled?'ON':'OFF'}</span></label></div>`;
