function payload(){const form=$('view-form'),p={view:current};form?.querySelectorAll('input,textarea,select').forEach(el=>{if(el.type!=='password'&&el.type!=='file'&&el.id!=='heygen-key'&&!el.hasAttribute('data-queue-story'))p[el.id]=el.type==='checkbox'?el.checked:el.value;});p.queue=[...(form?.querySelectorAll('[data-queue-story]:checked')||[])].map(el=>el.value);if(typeof p.audioFirstEnabled==='boolean')p.queueAudioMode=p.audioFirstEnabled?'audio_first':'native';if(p.to==='')delete p.to;return p;}
async function runAction(action,p=payload()){
 remember();
 if(action==='render_multilingual'&&['settings','audio'].includes(current))p={...p,story:p.multilingualStory,view:'agent'};
 if(action==='prepare_audio_first'&&['settings','audio'].includes(current))p={...p,story:p.audioFirstStory,from:p.audioFirstFrom,to:p.audioFirstTo,view:'agent'};
 if(action==='preflight_script'){
  try{
   toast('Validating the full batch locally…');
   const result=await api('ready-script/preflight',p);
   $('prompt-title').textContent=`Import preflight · ${result.reports.length} stories`;
   $('prompt-text').value=result.reports.map(r=>[
    `Story ${r.storyNumber||'?'} — ${r.title}`,`Preset: ${r.preset} | ${r.production_profile}`,
    `${r.clips} clips × ${r.clip_seconds}s = ${r.total_seconds}s`,
    `Locations: ${JSON.stringify(r.locations,null,2)}`,`Continuity: ${r.continuity||'(not supplied)'}`,
    ...r.warnings.map(w=>'WARNING: '+w),r.note,
    ...r.scenes.map(scene=>`\nCLIP ${scene.number} · ${scene.word_count} words · source line ${scene.source_line||'?'}\nNarration: ${scene.narration}\n${scene.shots.map((shot,i)=>`Shot ${i+1}: ${shot.start_seconds}–${shot.end_seconds}s — ${shot.visual}`).join('\n')}\nEffect: ${scene.effect}\nSound: ${scene.sound}\n\nEXPORTED PROMPT:\n${scene.prompt}`)
   ].join('\n')).join('\n\n========================================\n\n');
   $('prompt-dialog').showModal();toast('Preflight passed. No generation credits used.');
  }catch(e){$('prompt-title').textContent='Import validation failed';$('prompt-text').value=e.message;$('prompt-dialog').showModal();}return;
 }
 if(action==='retry'){
  try{const job=await api('retry',{view:current});selectedJob=job.id;cursor=0;logLines=[];logView.reset('Resuming the saved failed step…');$('activity').classList.add('expanded');document.body.classList.add('log-open');toast('Resuming the saved workflow.');await pollJobs();}catch(e){toast(e.message,true);}return;
 }
 if(['generate','generate_queue','refs','manual','retry_failed'].includes(action)){
  if(action==='generate_queue'){p.rotateQueueAccounts=bootstrap.globalWorkflow.rotateQueueAccounts;p.videosPerAccount=bootstrap.globalWorkflow.videosPerAccount;}
  const text=action==='manual'?'This manual selection generates new versions, even when older clips exist.':action==='retry_failed'?'Retry only individual failed tiles. Completed clips will be retained.':'This request generates media in Flow using the selected settings.';
  if(action==='generate_queue'&&!p.queue.length){toast('Select at least one saved story for the batch.',true);return;}
  if(!await confirmAction(action==='generate_queue'?`Generate ${p.queue.length} stories?`:'Start '+(action==='refs'?'reference generation':'generation')+'?',action==='generate_queue'?`${p.queueAudioMode==='audio_first'?'Prepare every selected story’s external narration first (API credits may apply), then generate background-only videos and mix narration. ':''}Generate each selected full story, one at a time, in a separate new project. Uses Flow credits. Account allocation: ${p.rotateQueueAccounts?'ON — '+p.videosPerAccount+' videos per account, looping through the eligible list.':'OFF — all videos use the current account.'}`:text+'\nFlow credits may be spent.'))return;
 }
 if(action==='resume_generations'){
  if(!p.queue.length){toast('Select generation-only stories to finish.',true);return;}
  if(p.queue.some(path=>!library.find(s=>s.path===path)?.generationOnlyPending)){toast('Choose the Generation only filter and select pending stories.',true);return;}
  if(!await confirmAction('Resume '+p.queue.length+' generated stories?', 'Open each saved Gmail/project, download existing clips, Join and apply enabled Video Editing settings. No new project or generation.'))return;
 }
 if(action==='delete'){if(!await confirmAction('Move all video clips to Trash?',p.project+'\nImages, characters and local video files are retained.'))return;p.confirmed=true;}
 if(action==='account_remove'){if(!await confirmAction('Remove account from the pool?',p.label+'\nThis removes the saved account entry.'))return;p.confirmed=true;}
 if(action==='account_use'||action==='account_activate'){if(!await confirmAction('Make this account active for automation?',p.label+'\nThe current automation browser profile will close and this Google account profile will be opened.'))return;}
 try{
  let job=await api('jobs',{action,payload:p});
  if(job.requiresDuplicateConfirmation){
   const details=job.duplicates.map(x=>`${x.title} (${x.preset}) — ${x.existing.length?'already saved': 'repeated in this batch'}`).join('\n');
   if(!await confirmAction('Story / batch already exists — Ignore and Override?',details+'\n\nContinue to process these stories again? Existing downloaded clips are retained. Cancel to leave them unchanged.'))return;
   job=await api('jobs',{action,payload:{...p,duplicateOverride:true}});
  }
  selectedJob=job.id;cursor=0;logLines=[];logView.reset('Starting…');$('activity').classList.add('expanded');document.body.classList.add('log-open');toast('Job started. Follow its progress below.');await pollJobs();
 }catch(e){toast(e.message,true);}
}
